CREATE SCHEMA IF NOT EXISTS staging;
CREATE SCHEMA IF NOT EXISTS dwh;
CREATE SCHEMA IF NOT EXISTS analytics;
CREATE TABLE IF NOT EXISTS staging.sellers (seller_id INTEGER PRIMARY KEY, seller_name TEXT NOT NULL, region TEXT);
CREATE TABLE IF NOT EXISTS staging.products (product_id INTEGER PRIMARY KEY, seller_id INTEGER NOT NULL, product_name TEXT, category TEXT, price NUMERIC(14,2));
CREATE TABLE IF NOT EXISTS staging.customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT);
CREATE TABLE IF NOT EXISTS staging.orders (order_id TEXT PRIMARY KEY, dt DATE NOT NULL, seller_id INTEGER NOT NULL, product_id INTEGER NOT NULL, customer_id INTEGER, quantity INTEGER NOT NULL, unit_price NUMERIC(14,2), amount NUMERIC(14,2) NOT NULL, status TEXT);
CREATE INDEX IF NOT EXISTS idx_staging_orders_dt ON staging.orders(dt);
CREATE TABLE IF NOT EXISTS dwh.dim_seller (seller_key INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, seller_id INTEGER UNIQUE NOT NULL, seller_name TEXT, region TEXT);
CREATE TABLE IF NOT EXISTS dwh.dim_product (product_key INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, product_id INTEGER UNIQUE NOT NULL, product_name TEXT, category TEXT, price NUMERIC(14,2));
CREATE TABLE IF NOT EXISTS dwh.dim_customer (customer_key INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, customer_id INTEGER UNIQUE NOT NULL, customer_name TEXT);
CREATE TABLE IF NOT EXISTS dwh.dim_date (date_key INTEGER PRIMARY KEY, full_date DATE UNIQUE NOT NULL, year INTEGER, month INTEGER, day INTEGER);
CREATE TABLE IF NOT EXISTS dwh.fact_orders (order_id TEXT PRIMARY KEY, dt DATE NOT NULL, seller_key INTEGER NOT NULL REFERENCES dwh.dim_seller(seller_key), product_key INTEGER NOT NULL REFERENCES dwh.dim_product(product_key), customer_key INTEGER REFERENCES dwh.dim_customer(customer_key), date_key INTEGER NOT NULL REFERENCES dwh.dim_date(date_key), quantity INTEGER NOT NULL, amount NUMERIC(14,2) NOT NULL, commission NUMERIC(14,2) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_fact_dt ON dwh.fact_orders(dt);
CREATE TABLE IF NOT EXISTS analytics.daily_summary (dt DATE PRIMARY KEY, total_orders INTEGER, revenue NUMERIC(16,2), average_basket NUMERIC(16,2), commission NUMERIC(16,2));
CREATE TABLE IF NOT EXISTS analytics.sales_anomalies (dt DATE PRIMARY KEY, revenue NUMERIC(16,2), average_previous_7_days NUMERIC(16,2), ratio NUMERIC(10,4), is_anomaly BOOLEAN);
CREATE TABLE IF NOT EXISTS analytics.pipeline_runs (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, run_date DATE, started_at TIMESTAMPTZ DEFAULT NOW(), finished_at TIMESTAMPTZ, status TEXT, error_message TEXT, rows_loaded INTEGER);
CREATE OR REPLACE VIEW analytics.seller_daily AS SELECT f.dt,s.seller_id,s.seller_name,COUNT(DISTINCT f.order_id) AS orders,SUM(f.amount) AS revenue,SUM(f.commission) AS commission FROM dwh.fact_orders f JOIN dwh.dim_seller s USING(seller_key) GROUP BY f.dt,s.seller_id,s.seller_name;
CREATE OR REPLACE VIEW analytics.category_daily AS SELECT f.dt,p.category,COUNT(DISTINCT f.order_id) AS orders,SUM(f.amount) AS revenue FROM dwh.fact_orders f JOIN dwh.dim_product p USING(product_key) GROUP BY f.dt,p.category;
CREATE OR REPLACE VIEW analytics.inactive_sellers AS SELECT s.seller_id,s.seller_name,MAX(f.dt) AS last_sale FROM dwh.dim_seller s LEFT JOIN dwh.fact_orders f ON f.seller_key=s.seller_key GROUP BY s.seller_id,s.seller_name HAVING MAX(f.dt) < CURRENT_DATE - INTERVAL '7 days' OR MAX(f.dt) IS NULL;
CREATE OR REPLACE VIEW analytics.suspicious_prices AS SELECT product_id,product_name,category,price FROM dwh.dim_product WHERE price <= 0 OR price > 10000;
